//! Comparación documental: mismos mensajes de sistema y usuario, plantilla Harmony.
use std::{fs,io::{Read,Write},net::TcpStream,time::{Duration,Instant,SystemTime,UNIX_EPOCH},process::Command,path::PathBuf};
use serde_json::{json,Value};
#[path="../tokenization.rs"]mod tokenization;
type Result<T>=std::result::Result<T,Box<dyn std::error::Error+Send+Sync>>;
fn now()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs()}
fn http(port:u16,method:&str,path:&str,body:&str,seconds:u64)->Result<Value>{let mut s=TcpStream::connect(("127.0.0.1",port))?;s.set_read_timeout(Some(Duration::from_secs(seconds)))?;write!(s,"{method} {path} HTTP/1.0\r\nHost: localhost\r\nConnection: close\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{body}",body.len())?;let mut v=String::new();s.take(8*1024*1024+1).read_to_string(&mut v)?;if v.len()>8*1024*1024{return Err("Respuesta excedida".into())}let(h,b)=v.split_once("\r\n\r\n").ok_or("HTTP incompleto")?;if h.split_whitespace().nth(1)!=Some("200"){return Err(format!("Rechazo: {h}: {b}").into())}Ok(serde_json::from_str(b)?)}
fn stop()->Result<()>{if !Command::new("timeout").args(["15","systemctl","stop","sv-conversacion-motor.service"]).status()?.success(){return Err("Parada no confirmada".into())}let p=Command::new("systemctl").args(["show","sv-conversacion-motor.service","-p","MainPID","--value"]).output()?;if String::from_utf8_lossy(&p.stdout).trim()!="0"{return Err("Motor todavía activo".into())}Ok(())}
fn main()->Result<()>{
 let a:Vec<_>=std::env::args().collect();if a.len()!=4{return Err("Uso: ENTRADAS DIRECTORIO_NUEVO PLAZO_UNIX".into())}let input:Value=serde_json::from_slice(&fs::read(&a[1])?)?;let dir=PathBuf::from(&a[2]);let deadline:u64=a[3].parse()?;fs::create_dir(&dir)?;fs::write(dir.join("ENTRADAS.json"),serde_json::to_vec_pretty(&input)?)?;
 let(t,derivation)=tokenization::load(&fs::read("/opt/sv-lab/conversacion-20260924/modelos/tokenizer.json")?)?;fs::write(dir.join("TOKENIZADOR.json"),serde_json::to_vec_pretty(&derivation)?)?;
 if !Command::new("timeout").args(["15","systemctl","start","sv-conversacion-motor.service"]).status()?.success(){return Err("Motor no iniciado".into())}
 let ready=Instant::now();while !http(8089,"GET","/v1/models","",2).is_ok_and(|v|v["data"].as_array().is_some_and(|a|a.iter().any(|m|m["status"]=="loaded"))){if ready.elapsed().as_secs()>180{stop()?;return Err("Motor no disponible".into())}std::thread::sleep(Duration::from_millis(500));}
 let mut out=fs::OpenOptions::new().create_new(true).write(true).open(dir.join("RESULTADOS.jsonl"))?;let started=now();let mut count=0;
 let outcome=(||->Result<()>{for case in input["cases"].as_array().ok_or("Sin casos")?{if now()+615>deadline{return Err("Plazo restante insuficiente".into())}
 let id=case["id"].as_str().ok_or("Sin ID")?;let prompt=format!("<|start|>system<|message|>{}<|end|><|start|>user<|message|>{}<|end|><|start|>assistant<|channel|>final<|message|>",case["system"].as_str().ok_or("Sin sistema")?,case["user"].as_str().ok_or("Sin pregunta")?);let ids=t.encode(prompt.clone(),false).map_err(|e|e.to_string())?.get_ids().to_vec();if ids.len()+192>4096{return Err("Contexto excesivo".into())}
 let request=json!({"model":"gguf","prompt":prompt,"temperature":0,"max_tokens":192,"logprobs":1,"echo_prompt":false,"stream":false});fs::write(dir.join(format!("{id}-PETICION.json")),serde_json::to_vec_pretty(&json!({"request":request,"ids":ids,"original":case,"conditions":"Temperatura cero, máximo 192 tokens y 600 segundos; mensajes originales y plantilla Harmony"}))?)?;
 let start=Instant::now();let response=http(8089,"POST","/v1/completions",&request.to_string(),600);let seconds=start.elapsed().as_secs_f64();
 match response{Ok(v)=>{let raw=v["choices"][0]["text"].as_str().unwrap_or("");let expected=if id=="DOC01"||id=="DOC04"{json!({"estado":"documentado","fuente":"OP-IMM-001-P10@1.0","cita":"Compara un recuento absoluto de neutrófilos válido con el intervalo de referencia aplicable."})}else{json!({"estado":"sin_respaldo","fuente":"","cita":""})};let parsed=serde_json::from_str::<Value>(raw);let accepted=parsed.as_ref().is_ok_and(|p|p==&expected)&&v["choices"][0]["finish_reason"]=="stop";serde_json::to_writer(&mut out,&json!({"case":id,"response":v,"seconds":seconds,"expected":expected,"accepted":accepted,"input_tokens":ids.len()}))?;out.write_all(b"\n")?;out.sync_all()?;count+=1;println!("DOCUMENTAL {id} accepted={accepted} seconds={seconds} answer={raw}");if v["usage"]["prompt_tokens"].as_u64()!=Some(ids.len() as u64){return Err("Recuento discordante".into())}},Err(e)=>{serde_json::to_writer(&mut out,&json!({"case":id,"error":e.to_string(),"seconds":seconds}))?;out.write_all(b"\n")?;out.sync_all()?;return Err(e)}}
 }Ok(())})();let stopped=if outcome.is_err(){Some(stop().is_ok())}else{None};fs::write(dir.join("RESUMEN.json"),serde_json::to_vec_pretty(&json!({"started":started,"ended":now(),"deadline":deadline,"rows":count,"error":outcome.as_ref().err().map(|e|e.to_string()),"engine_stopped_after_error":stopped}))?)?;outcome
}
